def transform(g):
    H,W=len(g),len(g[0]); out=[[0]*W for _ in range(H)]
    objs={}
    for r in range(H):
      for c in range(W):
        v=g[r][c]
        if v:
          if v not in objs: objs[v]=[]
          objs[v].append((r,c))
    seq=sorted(objs, key=lambda v:min(c for r,c in objs[v]))
    shapes=[]
    for v in seq:
      pts=objs[v]; r0=min(r for r,c in pts); c0=min(c for r,c in pts)
      cells={(r-r0,c-c0) for r,c in pts}; h=max(r for r,c in cells)+1; w=max(c for r,c in cells)+1
      shapes.append((v,cells,h,w))
    rr=cc=0
    for i,(v,cells,h,w) in enumerate(shapes):
      for dr,dc in cells:
        if 0<=rr+dr<H and 0<=cc+dc<W: out[rr+dr][cc+dc]=v
      if i+1<len(shapes):
        nh,nw=shapes[i+1][2:]
        # adjacent shapes share a corner along their extents
        rr += h-1; cc += w-1
    return out
